#include <cstdint>

struct Order {
    std::int64_t id;
    double price;
};

double read_price(Order order) {        // receives a copy
    return order.price;
}

double observe_price(const Order& order) {  // aliases, read-only
    return order.price;
}

void reprice(Order& order, double price) {  // aliases, may modify
    order.price = price;
}

auto mid(double bid, double ask) -> double {
    return (bid + ask) / 2.0;
}

int sequence = 0;

int next_bid() { return ++sequence; }
int next_ask() { return ++sequence; }

void publish(int bid_sequence, int ask_sequence);

void publish_in_order() {
    // Argument evaluation order is unspecified: the calls do not interleave,
    // but either may run first, so which argument gets 1 is the compiler's
    // choice. Statements are sequenced, so compute the effects separately.
    int bid_sequence = next_bid();
    int ask_sequence = next_ask();
    publish(bid_sequence, ask_sequence);
}

