#include <functional>

struct Order {
    double price;
    int quantity;

    double notional() const {
        return price * quantity;
    }
};

void member_pointer_demo() {
    Order order{101.5, 200};

    double Order::*price_member = &Order::price;
    double (Order::*notional_member)() const = &Order::notional;

    double p = order.*price_member;
    double n = (order.*notional_member)();  // parentheses required

    double p2 = std::invoke(price_member, order);
    double n2 = std::invoke(notional_member, order);

    (void)p; (void)n; (void)p2; (void)n2;
}

[[nodiscard]] bool send_order(int id, [[maybe_unused]] int retry_budget) {
    return id > 0;
}

void submit_and_ignore(int id) {
    // Deliberate: we are draining the queue and do not act on failures here.
    (void)send_order(id, 3);
}

