    double quantity;
};

struct Instrument {     // non-trivial member: copy machinery required
    std::string symbol;
    double tick_size;
};

// Scalar: copying costs no more than indirect access.
void set_ticks(int ticks);

// Small trivial aggregate: the ABI can keep both fields in registers.
double notional(Order order);

// Large or non-trivial read-only: avoid the copy.
bool is_tradable(const Instrument& instrument);

// Caller-owned and modified: the & makes the mutation explicit.
void reprice(Order& order, double price);

int make_value();
int& find_value();

void reference_binding_demo() {
    int quantity = 100;

    int& mutable_view = quantity;             // quantity is an lvalue
    const int& read_only = quantity + 1;      // quantity + 1 is a prvalue
    const int& returned_value = make_value(); // returns T: prvalue
    int& returned_ref = find_value();         // returns T&: lvalue

    // int& bad = quantity + 1;  // error: non-const lvalue ref cannot
                                 // bind to a prvalue

    mutable_view += 25;
    (void)read_only; (void)returned_value; (void)returned_ref;
}
